import { MustGetElement } from "#core/ui/utilities/utilities-dom.js";

import { UnitFlagFactory, UnitFlagFactoryMaker, UnitFlagType } from "#base/ui/unit-flags/unit-flag-manager.js";
import { GenericUnitFlag } from "#base/ui/unit-flags/unit-flags.js";

import styles from "#base/ui/unit-flags/unit-flags.scss?url";

interface PrivateerFlagType extends UnitFlagType {
	/** Runtime typecheck flag */
	kind: "privateerinterface";
}

/**
 * Factory to build privateer flags.
 */
class PrivateerFlagMaker implements UnitFlagFactoryMaker {
	initialize() {
		// Do nothing.
	}

	isMatch(unit: Unit, _unitDefinition: UnitDefinition, _others?: UnitFlagFactoryMaker[]): boolean {
		return unit.isPrivateer;
	}
	getComponentName(): string {
		return "privateer-flag";
	}
}

/**
 * Army Commander flags
 */
class PrivateerFlag extends GenericUnitFlag implements PrivateerFlagType {
	kind = "privateerinterface" as const;

	private privateerContainer!: HTMLElement;

	onAttach() {
		super.onAttach();

		this.privateerContainer = document.createElement("div");
		this.privateerContainer.classList.add("unit-flag__privateer-container", "absolute", "h-4", "w-4");

		const unitFlagPrivateerIcon = document.createElement("div");
		unitFlagPrivateerIcon.classList.add(
			"unit-flag__privateer",
			"bg-contain",
			"bg-no-repeat",
			"absolute",
			"inset-0",
		);
		this.privateerContainer.appendChild(unitFlagPrivateerIcon);
		// foo
		const unitFlagContainer = MustGetElement(".unit-flag__container", this.Root);
		unitFlagContainer.appendChild(this.privateerContainer);

		this.updateHealth();
	}

	updateHealth() {
		super.updateHealth();

		if (this.privateerContainer != undefined && this.unit.Health) {
			this.privateerContainer.classList.toggle("-top-5", this.unit.Health.damage > 0);
			this.privateerContainer.classList.toggle("-top-1", this.unit.Health.damage == 0);
		}
	}
}

Controls.define("privateer-flag", {
	createInstance: PrivateerFlag,
	description: "Privateer Unit Flag",
	classNames: ["unit-flag", "allowCameraMovement"],
	styles: [styles],
});

UnitFlagFactory.registerStyle(new PrivateerFlagMaker());
